<template><view class="posts" :class="{articles}"><view v-for="p in posts" :key="p.id" class="post" @click="go(p)" role="link" :aria-label="p.title"><image :src="media(p.thumbnail)" :mode="articles?'aspectFill':'aspectFill'" :lazy-load="true"/><view class="text"><text class="name">{{p.title}}</text><text v-if="articles && p.excerpt" class="excerpt">{{plain(p.excerpt)}}</text></view></view></view></template>
<script setup>import {go,media} from '../lib/content';defineProps({posts:{type:Array,default:()=>[]},articles:Boolean});const plain=s=>s.replace(/<[^>]*>/g,'').replace(/&[^;]+;/g,' ')</script>
<style scoped>.posts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:36rpx 20rpx;padding:0 40rpx}.post{min-width:0;overflow:hidden}.post image{width:100%;height:432rpx;border-radius:7rpx;display:block;background:#f3f3f3;box-shadow:0 3rpx 10rpx #0001}.text{padding:17rpx 0;text-align:center}.name{font-size:22rpx;color:#777;line-height:1.5}.articles{display:block}.articles .post{background:#fff;margin-bottom:60rpx;border-radius:6rpx}.articles .post image{height:284rpx;border-radius:0;box-shadow:none}.articles .text{padding:24rpx 30rpx 28rpx;text-align:left}.articles .name{font-size:28rpx;color:#111;line-height:1.65;display:block}.excerpt{display:block;border-top:1rpx solid #f0f0f0;margin-top:20rpx;padding-top:20rpx;color:#aaa;font-size:21rpx;line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}</style>
